        [52013] = "PHONE RESTORATION SUCCESSFUL",
        [52014] = "Your phone has been restored to its state at the time of the most recent available backup. If your phone was locked by a PIN at the last update, you'll need to enter your previous PIN to unlock your phone. In addition, you might need to manually sync photos to restore them to your phone.\nClick Finish to continue.",
        [52015] = "RESTORATION ERROR",
