        [52056] = "STATUS: PHONE CONNECTED TO {0} (SSID)",
        [52057] = "STATUS: PHONE NOT CONNECTED TO NETWORK",
        [52058] = "Keep your phone up to date with your latest media without having to plug into your computer—sync it over your home wireless network.\n\nTo get started, turn on your phone. On Start, flick left to Settings > System. Connect to the network you want to use for wireless sync and then click Refresh below.",
        [52059] = "Remember that when syncing wirelessly, the content on your phone is only as secure as your home wireless network.\n\nEnabling wireless sync will open ports on your computer that might otherwise be closed. You should be aware that open ports are less secure than closed ports.",
        [52060] = "ZUNE SOFTWARE SETTINGS",
        [52061] = "Choose your initial software settings.",
        [52062] = "START ME OFF WITH THE DEFAULT SETTINGS. I'LL CHANGE THEM LATER IF I WANT TO.",
        [52063] = "•  Add all media in my default Windows folders for music, videos, and pictures\n•  Make the Zune software my primary music and video player\n•  Download song and album information from the Internet\n•  Retrieve missing song information automatically\n•  Send Microsoft Zune-software usage data to help improve its products",
        [52064] = "I WANT TO CHANGE THE ZUNE SOFTWARE SETTINGS BEFORE I SET UP MY PHONE. SETTINGS INCLUDE:",
        [52065] = "•  Media locations (including external hard drives)\n•  Media types\n•  Privacy options",
