        [52111] = "Please read the agreement and click Accept to continue.",
        [52112] = "You can decide how much storage space you want to reserve on your phone for content you want to get and receive on your phone. For example, email, pictures, and videos you take, and apps and games you buy and download from the marketplace.\n\nThe more space you reserve, the more room you'll have for your stuff.",
        [52116] = "Your phone can't be used in its present condition and there are no restore points for it on this computer. Your phone might restart and return to normal if you disconnect it. For further assistance, contact your phone manufacturer.",
        [52117] = "Your phone has been updated with the latest software. \nClick finish to continue.",
