        [52129] = "Copying to phone...",
        [52130] = "Phone software",
        [52131] = "Linking your phone to a Zune Tag lets you share details of your listening on your custom Zune Card in the Zune Social. For more information, see www.zune.net/social.",
        [52132] = "Your phone is connected as a guest. You can still sync, just not automatically. To enable automatic syncing based on sync rules that you choose, click Change Sync Relationship. To clear the current sync relationship, click Forget This Phone.\n\nPlease note: If you change or clear the sync relationship, any videos downloaded at Zune Marketplace will be removed from the phone.",
