        [52195] = "KIN STUDIO",
        [52196] = "If your plan includes the KIN Studio, photos and share-quality videos will be automatically synced with KIN Studio, where you can view, share, and download them. If you're not using the KIN Studio, photos and videos will appear in your collection when you connect to your computer. Note that HD/HQ videos are only synced with your computer when you're connected via USB.",
        [52197] = "Go to KIN Studio",
        [52198] = "Estimated time: Calculating...",
        [52199] = "Do more with Windows Phone",
        [52200] = "Windows Live is the place to go to organize appointments, search contacts, sync Office documents and notes, lock a lost phone, and find a lost phone with Bing Maps.",
