        [52206] = "GUEST PHONE DETECTED",
        [52207] = "Your phone is connected to this computer as a guest. We recommend that you use your primary computer (the first computer you connected to) to install updates.",
        [52208] = "We weren't able to update your phone. Please try again. After updating, you might need to manually re-sync your pictures and other media.",
        [52239] = "We can't complete the update because there isn't enough room on your computer to store a backup of your phone. Try freeing up some space on your phone or your computer, and then try installing the update again.",
        [52240] = "Additional space needed on drive {0} {1:0.00} {2}",
        [52241] = "If you can't free up enough storage space, you can choose to update your phone without performing a backup first. If you choose this option, there will be no backup for you to restore in case the update doesn't install properly. This means you might not be able to recover lost personal data (such as settings, text messages, music, pictures, and videos) or, in rare cases, to use your phone.",
        [52242] = "Update without backing up my phone",
        [52243] = "Please wait while we determine the amount of disk space required to complete the update.",
        [52244] = "If the update doesn't install properly and you need to restore your phone to its previous state, we might not be able to restore all of your phone's content.  \n\nTo review the sync errors, click Cancel and go to the phone summary. To continue updating the phone, click Next.",
        [52245] = "We can't sync all of your phone's content with your computer.",
        [52246] = "If you continue restoring your phone, you might lose some of the content on your phone since we weren't able to sync all of it. \n\nTo review the sync errors, click Cancel and go to the phone summary. To continue restoring your phone, click Next.",
        [52249] = "Your phone has been updated. We're checking for additional updates.",
        [52251] = "CHECKING FOR ADDITIONAL UPDATES...",
        [52252] = "If you choose to install the update as a guest, we won't back up your music, pictures, and videos. If the update doesn't install properly and you use this computer to restore your phone, you'll lose the music, pictures, and videos that are currently on your phone.\n\nIf you're using a PIN lock, you'll need to enter your PIN for each update.\n\nTo continue updating as a guest, click Next.",
        [52253] = "This process will install all available updates and could take anywhere from 30 minutes to several hours, depending on the number of updates.",
